import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第十三章","description":"《正易心法》第十三章——坎兑二水，明须识破：坎为一阳陷阴中之乾水（气之液），兑为一阴浮阳上之坤水（形之散）；以井卦卦变、《月令》物候、炼丹井、医经四重验证。","frontmatter":{"title":"正易心法·第十三章","description":"《正易心法》第十三章——坎兑二水，明须识破：坎为一阳陷阴中之乾水（气之液），兑为一阴浮阳上之坤水（形之散）；以井卦卦变、《月令》物候、炼丹井、医经四重验证。","category":"guide","aliases":["正易心法第十三章","坎兑二水","坎乾水兑坤水"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-13.md","filePath":"yijing/zheng-yi-xin-fa/chapter-13.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-13.md"},k=p({...c,setup(u){const i=[{id:"z13-01",label:"一、明须识破",showLabel:!0,sentences:[["坎兑二水，明须",{text:"识破",glossary:"shipo"},"。坎",{text:"润",glossary:"run"},"兑",{text:"说",glossary:"yue"},"，理自不同。"]],note:["坎与兑同为水，必须看清楚、辨明白：坎是润泽，兑是喜悦散布，道理本自不同。（这是第十二章「八字通用原则」的第一个具体应用——两者都与「水」有关，但卦画结构不同，**必须从卦画结构区分，不能只看「水」这个文字标签**。）"]},{id:"z13-02",label:"二、坎乾水兑坤水",showLabel:!0,sentences:[["坎，",{text:"乾水",glossary:"qianshui"},"也，气也，若井是也。兑，",{text:"坤水",glossary:"kunshui"},"也，形也，今雨是也。"]],note:["坎，是乾阳之水，是气，就像井水一样；兑，是坤阴之水，是形，就像雨水一样。（这极其反直觉：直觉上水是阴性的，怎么坎水反而是「乾水」？麻衣的逻辑是——**坎的卦画是一阳陷于二阴之中 = 乾阳被坤阴包裹 = 外表是阴（水的形质），内里是阳（乾气的潜藏）**。兑的卦画是一阴浮于二阳之上 = 坤阴浮在乾阳之上，本质是坤阴的外散。）"]},{id:"z13-03",label:"三、坎以气潜行",showLabel:!0,sentences:[["一阳中陷为二阴为坎，坎以气潜行于万物之中，为受命之根本，故曰：润万物者莫润乎水。盖润，液也，气之液也。"]],note:["坎卦是一阳陷入二阴之中——坎水以气的形式潜行于万物之中，是万物受命的根本。所以说「润泽万物，没有比水更能润泽的」；这个「润」，是液化的意思，是气凝结为液的状态。（方向：**由外向内、由上向下，潜行渗透**——象如井水渗入土壤，滋养根系。）"]},{id:"z13-04",label:"四、兑以形普施",showLabel:!0,sentences:[["一阴上彻于二阳为兑，兑以形普施于万物之上，为发生之利泽，故曰：说万物者莫说乎泽。盖说，散也，形之散也。"]],note:["兑卦是一阴上彻于二阳之上——兑水以形质的方式普遍施与万物之上，是促进万物发生的恩泽。所以说「使万物喜悦，没有比泽更能使万物喜悦的」；这个「说（悦）」，是散布的意思，是形质散布施与的状态。（方向：**由内向外、由上向下，普遍散布**——象如雨水从天而降，普施大地。注意「说」在此通「悦」。）"]},{id:"z13-05",label:"五、依文解义不知落处",showLabel:!0,sentences:[["坎、兑二水，其理昭昭如此。学者",{text:"依文解义",glossary:"yiwenJieyi"},"，不知",{text:"落处",glossary:"luochu"},"，其能得实用乎？自汉诸儒不得其说，故真人发其端。"]],note:["坎、兑二水，道理如此昭然。学者只依文字解义、不知落处，怎能得到实际的用处？（「真人发其端」是麻衣少见的自我指认。这一句与第一章「学者不知落处，则所谓玩占者，亦虚语耳」完全同调——**「落处」在第一章是总纲，在本章是具体案例**：坎水的落处是乾阳潜藏于阴中（井水、肾水、地下水），兑水的落处是坤阴散布于阳上（雨水、泽水、地表水）。）"]},{id:"z13-06",label:"六、井卦与月令",showLabel:!0,sentences:[["又论，且以井卦观之，本来泰卦初爻易五，是为井，则知一阳升而为坎水也。故《月令》云：“仲冬，水泉动，仲冬一阳生。”至仲秋，乃云：“杀气侵盛，阳气日衰，水始涸。”信乎坎之为乾水也！"]],note:["再论：以井卦来看，井卦本来是泰卦的初爻与五爻互换而成，由此可知一阳上升即为坎水。所以《月令》说「仲冬，水泉涌动——仲冬一阳初生」；到了仲秋，又说「杀气渐盛，阳气日衰，水开始干涸」。这正验证了坎水是乾阳之水！（**水的枯荣跟随阳气的消长**——仲冬一阳生则水泉动，仲秋阳气衰则水始涸。这是四重证据中的第二重。）"]},{id:"z13-07",label:"七、炼丹井与医经",showLabel:!0,sentences:[["道家有",{text:"炼丹井",glossary:"liandanJing"},"，海外女国无男，",{text:"窥井即生",glossary:"kuijingJisheng"},"。《医经》：“无子妇人，男服口脂，循井即孕。”其为乾阳，皆可明验。若曰：天降时雨，山川出云，又曰：地气上为云，天气下为雨，此兑之所以为坤水也。"]],note:["道家有炼丹井，海外女国无男，女子窥井即可受孕；《医经》说：「无子的妇人，男子服口脂，循井即可受孕。」这些都是坎水含乾阳的明证。（这两条是「民俗与医经」层面的旁证——看似荒诞，指向的都是同一件事：**井水含乾阳，故有生育之力**。最后一句转到兑：「天降时雨，山川出云」「地气上为云，天气下为雨」，正是兑水作为坤阴之水的道理——**雨水从上而降，是坤阴之形的外散**。至此四重验证完备：卦理、物候、卦变、民俗医经，坎兑二水各归其位。）"]}],o=[{id:"shipo",term:"识破",pinyin:"shí pò",meaning:"看穿、辨清。必须分清坎兑二水的本质差异。"},{id:"run",term:"润",pinyin:"rùn",meaning:"滋润渗透。麻衣解作「液也，气之液」——气凝为液，向内渗透，是坎水之德。"},{id:"yue",term:"说",pinyin:"yuè",meaning:"通「悦」，此处解作「散」——「形之散」，向外散布施与，是兑水之德。"},{id:"qianshui",term:"乾水",pinyin:"qián shuǐ",meaning:"属于乾阳系统的水。坎为坤体藏乾阳，故水中有阳气，如井水、地下水。"},{id:"kunshui",term:"坤水",pinyin:"kūn shuǐ",meaning:"属于坤阴系统的水。兑为乾体藏坤阴，故水是纯阴形质，如雨水。"},{id:"yiwenJieyi",term:"依文解义",pinyin:"yī wén jiě yì",meaning:"只从文字表面理解。麻衣批评不看卦画、只看文字的学者。"},{id:"luochu",term:"落处",pinyin:"luò chù",meaning:"卦象的具体对应位置。第一章核心概念，本章再次点出。"},{id:"liandanJing",term:"炼丹井",pinyin:"liàn dān jǐng",meaning:"道家用井水炼丹，所取为井水中所含的乾阳。"},{id:"kuijingJisheng",term:"窥井即生",pinyin:"kuī jǐng jí shēng",meaning:"望入井中即可受孕。传说的海外女国，谓井水含乾阳，有生育之力。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t("",21)),e(r,{colophon:"坎乾水 · 兑坤水 · 气之液 · 形之散",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十三章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（「说」通「悦」、「曰为天之气」之「曰」等），不作统一。原文末段「凡此卦画，皆所以写天地万物之理于目前」一句据底本属本章末，本页依底本分段。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"坎为乾水",pinyin:["kǎn","qián"],meaning:"坎是一阳陷于二阴中＝乾阳被坤阴包裹，外表是水（阴），内里是阳（乾气）——「气之液」，如井水、地下水、肾水。"},{term:"兑为坤水",pinyin:["duì","kūn"],meaning:"兑是一阴浮于二阳上＝坤阴浮在乾阳之上，是阴形外散——「形之散」，如雨水。"},{term:"气之液 · 形之散",pinyin:["qì","zhī"],meaning:"润＝气之液（向内渗透）；说（悦）＝形之散（向外散布）。这是坎兑二水最精要的两个定义。"},{term:"井卦卦变",pinyin:["jǐng","guà"],meaning:"井卦是泰卦初爻与五爻互换而成——一阳上升被坤阴包裹即坎，验证「坎水是乾阳之气上升」。"},{term:"月令物候",pinyin:["yuè","lìng"],meaning:"仲冬一阳生则「水泉动」，仲秋阳气衰则「水始涸」——水的枯荣跟随阳气消长。"},{term:"炼丹井",pinyin:["liàn","dān"],meaning:"道家用井水炼丹，所取为井水中的乾阳。内丹「取坎填离」的原料，与此同理。"}]}),n[3]||(n[3]=t("",26))])}}});export{m as __pageData,k as default};
